import { auth, signOut } from "@/auth";
import { getUser, listUsers } from "@/lib/users";

export default async function DashboardPage() {
  // Middleware already redirects unauthenticated requests to /signin, so
  // session.user is expected here — but stay defensive rather than assume.
  const session = await auth();
  const me = session?.user?.id ? await getUser(session.user.id) : undefined;
  const all = await listUsers();

  return (
    <main className="mx-auto max-w-2xl p-8">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-semibold">Dashboard</h1>
        <form
          action={async () => {
            "use server";
            await signOut({ redirectTo: "/signin" });
          }}
        >
          <button type="submit" className="text-sm font-medium underline">
            Sign out
          </button>
        </form>
      </div>
      <p className="mt-2 text-sm opacity-70">
        Signed in as {me?.name ?? "nobody"} ({me?.email ?? "—"})
      </p>

      <h2 className="mt-8 text-lg font-medium">Team</h2>
      <ul className="mt-2 space-y-1">
        {all.map((u) => (
          <li key={u.id} className="text-sm">
            {u.name} — {u.email} — joined {u.createdAt}
          </li>
        ))}
      </ul>
    </main>
  );
}

