import bcrypt from "bcryptjs";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

type InternalUser = User & {
  // Absent for accounts that only ever signed in via an OAuth provider (e.g. Google).
  passwordHash?: string;
};

const users: InternalUser[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

let nextId = users.length + 1;

function toPublicUser(user: InternalUser): User {
  const { passwordHash: _passwordHash, ...publicUser } = user;
  return publicUser;
}

export async function listUsers(): Promise<User[]> {
  return users.map(toPublicUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const user = users.find((u) => u.id === id);
  return user ? toPublicUser(user) : undefined;
}

export async function findUserByEmail(email: string): Promise<User | undefined> {
  const user = users.find((u) => u.email.toLowerCase() === email.toLowerCase());
  return user ? toPublicUser(user) : undefined;
}

/**
 * Verifies email + password against the store. Returns the public user on
 * success, or undefined if the email is unknown, has no password set (e.g.
 * Google-only account), or the password doesn't match.
 */
export async function verifyPassword(
  email: string,
  password: string
): Promise<User | undefined> {
  const user = users.find((u) => u.email.toLowerCase() === email.toLowerCase());
  if (!user || !user.passwordHash) return undefined;
  const valid = await bcrypt.compare(password, user.passwordHash);
  return valid ? toPublicUser(user) : undefined;
}

export async function createUserWithPassword(
  email: string,
  password: string,
  name: string
): Promise<User> {
  const existing = users.find((u) => u.email.toLowerCase() === email.toLowerCase());
  if (existing) {
    throw new Error("A user with that email already exists.");
  }
  const passwordHash = await bcrypt.hash(password, 10);
  const user: InternalUser = {
    id: String(nextId++),
    email,
    name,
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash,
  };
  users.push(user);
  return toPublicUser(user);
}

/**
 * Finds or creates a user for an OAuth sign-in (e.g. Google), matched by
 * email. Used so credentials and OAuth sign-ins share the same user record.
 */
export async function upsertOAuthUser(email: string, name: string): Promise<User> {
  const existing = users.find((u) => u.email.toLowerCase() === email.toLowerCase());
  if (existing) return toPublicUser(existing);
  const user: InternalUser = {
    id: String(nextId++),
    email,
    name,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  return toPublicUser(user);
}

